int kvm_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_dev_ops *ops;
	struct kvm_device *dev;
	int r, fd;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_dev_ops[cd->type];
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_lock(kvm);
	r = -EINVAL;
	if (ops->create_dev)
		r = ops->create_dev(kvm, cd, dev);
	if (r) {
		kvm_unlock(kvm);
		goto unlock;
	}

	list_add(&dev->list, &kvm->devices);
	dev->ops = ops;
	dev->kvm = kvm;
	kvm_get_kvm(kvm);
	kvm_unlock(kvm);

	if (ops->init_dev) {
		r = ops->init_dev(dev);
		if (r)
			goto init_dev_failed;
	}

	fd = kvm_dev_ioctl_create_device(dev, NULL);
	if (fd < 0) {
		r = fd;
		goto init_dev_failed;
	}

	cd->fd = fd;
	return 0;

init_dev_failed:
	ops->destroy_dev(dev);
unlock:
	kfree(dev);
	return r;
}

int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int r, createflags;

	if (cd->type >= KVM_DEV_TYPE_MAX || !kvm_dev_ops[cd->type])
		return -EINVAL;

	ops = kvm_dev_ops[cd->type];
	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	dev->kvm = kvm;
	dev->ops = ops;
	dev->id = cd->id;

	mutex_lock(&kvm->lock);
	r = ops->create(dev, cd->flags);
	if (r) {
		mutex_unlock(&kvm->lock);
		goto out_free_dev;
	}

	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init) {
		r = ops->init(dev);
		if (r)
			goto out_remove_dev;
	}

	cd->fd = kvm_dev_ioctl_create_device(dev, &createflags);
	if (cd->fd < 0) {
		r = cd->fd;
		goto out_deinit;
	}

	return 0;

out_deinit:
	if (ops->init)
		ops->init(dev);
out_remove_dev:
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
out_free_dev:
	kfree(dev);
	return r;
}

int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int ret = -EINVAL;

	if (!kvm || !cd)
		return -EINVAL;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return ret;

	const struct kvm_device_ops *ops = kvm_dev_ioctl_ops[cd->type];
	if (!ops)
		return ret;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	struct kvm_device *dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_lock(kvm);

	dev->kvm = kvm;
	dev->ops = ops;

	ret = ops->create(dev, cd->fd, cd->flags);
	if (ret) {
		kvm_unlock(kvm);
		goto out_free;
	}

	list_add(&dev->list, &kvm->devices);

	if (ops->init) {
		ret = ops->init(dev);
		if (ret) {
			kvm_unlock(kvm);
			goto out_remove;
		}
	}

	ret = kvm_ioctl_create_device(kvm, cd->fd, dev);

	if (ret) {
		kvm_unlock(kvm);
		goto out_cleanup;
	}

	kvm_unlock(kvm);

	return 0;

out_cleanup:
	if (ops->release)
		ops->release(dev);
out_remove:
	list_del(&dev->list);
out_free:
	kfree(dev);
	return ret;
}

#include <linux/kvm.h>
#include <linux/slab.h>
#include <linux/file.h>

int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
    int r = -EINVAL;
    struct kvm_device_ops *ops;
    struct kvm_device *dev;

    if (cd->type >= KVM_DEV_TYPE_MAX)
        return r;

    ops = kvm_find_device_ops(cd->type);
    if (!ops)
        return r;

    if (cd->flags & KVM_CREATE_DEVICE_TEST)
        return 0;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->ops = ops;
    dev->kvm = kvm;
    dev->id = cd->id;

    mutex_lock(&kvm->lock);
    r = ops->create(dev, cd);
    if (r) {
        mutex_unlock(&kvm->lock);
        goto out_free;
    }

    list_add(&dev->list, &kvm->devices);
    mutex_unlock(&kvm->lock);

    if (ops->init) {
        r = ops->init(dev);
        if (r)
            goto out_remove;
    }

    cd->fd = get_ufd();
    if (!cd->fd) {
        r = -ENODEV;
        goto out_remove;
    }

    return 0;

out_remove:
    mutex_lock(&kvm->lock);
    list_del(&dev->list);
    mutex_unlock(&kvm->lock);
out_free:
    kfree(dev);
    return r;
}
